UPDATE juhe_business.providers
SET default_supported_models_json = (default_supported_models_json::jsonb - 'codex-auto-review')::text,
    updated_at = now()
WHERE code = 'gpt'
  AND default_supported_models_json::jsonb ? 'codex-auto-review';

